local ax,bx={},nil
for cx=0,_w and _w.max or-1 do
local dx=_w[cx]
if dx and dx.atk and dx.atk~=bx then
bx=dx.atk
local ex,gx=pcall(R.attackInfo,dx.atk,dx.range)
table.insert(ax,{from=cx,id=dx.atk,does=ex and bb.atkBrief(gx)or nil})
if#ax>=6 then
break
end
end
end
return ax
end
