end
local hM=math.min(dM,gM)
local iM=hb.base(cM)
if iM<=0 then
return 0,hM
end
return hb.share(cM.unit_id)*(hb.score(hb.whatIf(cM,{xp=eM+hM}))/iM-1)*100,hM
end
function hb.gainFuse(jM)
