function hb.xpRate()
local lP=L.session()
if not lP then
return 0
end
local mP=0
for nP,oP in ipairs(hb.core())do
local pP=lP.collection:get_unit_by_uuid(oP)
if pP then
local qP,rP=hb.gainXp(pP,500000)
if rP>0 then
mP=math.max(mP,qP/rP)
end
end
end
local sP=mP*(M.strengthValue or 300)
if(tonumber(L.cur(Jcd[1642]))or 0)>(M.xpGoldFloor or 100000)then
sP=math.min(sP,(L.GOLD_VALUE or 0.02)/14)
end
