function hb.xpGuess(tP)
local uP=tP.level and L.Levels[tP.level]
if not uP then
return 0
end
local vP=math.min(9,tonumber(uP.story_world_rank)or tonumber(tP.rank)or 9)
local wP=tonumber(uP.story_level_rank)or 6
local xP=(tP.kind==Jcd[1616]and 1.5 or 1)*(vP>5 and 2 or 1)
local yP=2.1564^(vP-1)*(40+10*wP)/xP
if tP.kind==Jcd[1599]then
yP=3*30*2.1564^(vP-1)/xP
end
local zP=vP>=9 and 0.3 or(vP>=7 and 0.5 or 1)
return yP*zP*6
end
function hb.modeBonus(AP)
