local TP,UP,VP={},0,0
for WP,XP in ipairs(hb.foodHeld())do
local YP=XP.xp*RP
local ZP=math.min(XP.n,math.floor((SP-UP)/math.max(1,YP)))
if ZP>0 then
TP[XP.id]=ZP
UP=UP+ZP*YP
VP=VP+ZP
end
end
return{feed=TP,planned=UP,n=VP}
end
