local kT,lT,mT=pcall(L.USC.is_unit_good_for_fusion,NS,jT)
if kT and lT and not(iT._locked or jT._locked)and not QS[hT]and not RS[jT.unit_id]and not(iT._equipped_relic or jT._equipped_relic)and not(iT.shiny or jT.shiny)and not R.trait(jT)and not(iT.further_modifiers and iT.further_modifiers.limit_break)then
local nT=eb.fodderOrder(jT.unit_id)
if nT and not eT[hT]then
local oT,pT=pcall(R.score,jT)
table.insert(fT,{uuid=hT,id=jT.unit_id,pts=tonumber(mT)or 1,sc=oT and pT or 0,order=nT})
gT=gT+(tonumber(mT)or 1)
