end
if#JV==0 then
V.pickNote.autoFuseXp=Jcd[2366]
return
end
if os.time()-(tonumber(M.fuseXpOnAt)or 0)<30 then
V.pickNote.autoFuseXp=Jcd[2367]
return
end
V.pickNote.autoFuseXp=nil
if E.req.back.fuseXp and Q.now()<E.req.back.fuseXp then
return
end
V.fuseBatch=V.fuseBatch or 50
local MV,NV,OV=0,0,{}
while E.alive and MV<10 and not N.pauseAll do
if MV>0 then
local PV,QV,RV=V.xpFodder(GV.collection:get_unit_by_uuid(M.fuseXpUnit)or HV)
JV,LV={},RV
for SV,TV in ipairs(PV)do
