function cb.holdGain(vdb,wdb,xdb,ydb)
if not vdb or(wdb or 0)<=0 then
return 0
end
local zdb,Adb=tonumber(vdb.stun)or 0,tonumber(vdb.slowTime)or 0
if zdb<=0 and Adb<=0 then
return 0
end
local Bdb,Cdb=zdb>0 and zdb or Adb,zdb>0 and 1 or(tonumber(vdb.slowPct)or 0.3)
local Ddb=Cdb*Bdb/(Bdb+(tonumber(vdb.ccCd)or 8))
local Edb=Ddb/math.max(0.1,1-Ddb)
return wdb*Edb*Q.clamp(xdb or 0.5,0,1)*math.min(1,(tonumber(vdb.n)or 1)/2)/(1+(ydb or 0))
end
function cb.bleedGain(Fdb,Gdb,Hdb,Idb)
if(Fdb or 0)<=0 then
return 0
end
local Jdb=Gdb or 0
for Kdb,Ldb in ipairs(Hdb or{})do
Jdb=math.max(Jdb,(tonumber(Ldb.hp)or 0)*0.5)
