function cb.keepsUp(Qdb,Rdb,Sdb,Tdb,Udb)
local Vdb=Qdb.coming
if not(Vdb and#Vdb>0 and Qdb.waveSec)then
return true
end
local Wdb=Qdb.eff or 1
local Xdb=Qdb.money-Sdb
local Ydb=(Qdb.teamDps or 0)*(Qdb.shieldK or 1)+(Tdb or 0)*Wdb+cb.dpsFor(Rdb,math.max(0,Xdb))*Wdb
local Zdb=(Qdb.farmNow or 0)+(Udb or 0)
local _db=(Qdb.roadSec or 130)*Q.clamp(Qdb.cover or 0.6,0.1,1)
local aeb=Qdb.hpAlive or 0
for beb,ceb in ipairs(Vdb)do
aeb=math.max(0,aeb+ceb.hp-Ydb*Qdb.waveSec)
local deb=Ydb*_db
if aeb>deb then
return false,beb,deb/math.max(1,aeb)
end
if beb< #Vdb then
Ydb=Ydb+cb.dpsFor(Rdb,(ceb.reward or 0)+Zdb)*Wdb*(0.85^beb)
end
end
return true
end
function cb.decide(eeb,feb)
local geb=Q.clamp(feb.cover or 0.6,0.1,1)
local heb=math.max(M.clearSec,0.7*(feb.roadSec or 50)*geb)
local ieb=(feb.clearSec or 0)>heb
feb.piling=feb.piling and ieb
local jeb=feb.attackers>0 and feb.pressure<math.min(M.safeReach,geb*0.75)and not feb.piling and not ieb
local keb=feb.pressure>=math.min(M.dangerReach,geb*0.9)or(feb.piling and feb.enemies>=18)
local leb,meb
for neb,oeb in ipairs(eeb)do
if oeb.farm then
if M.farmUnits and oeb.gain>0 then
oeb.payback=oeb.cost/oeb.gain
if feb.left-1>=oeb.payback+(feb.farmSpare or M.farmSpare)and(not leb or oeb.payback<leb.payback)then
leb=oeb
end
end
else
oeb.ratio=oeb.gain/math.max(1,oeb.cost)
if not meb or oeb.ratio>meb.ratio then
meb=oeb
end
end
end
if feb.leak and feb.attackers>0 then
local peb
for qeb,reb in ipairs(eeb)do
local seb=not feb.airLeak or(reb.e and W.cardAir(reb.e.id))
if reb.place and not reb.farm and seb and reb.cost<=feb.money and not(reb.e and R.allyBuff(reb.e.id))and(not peb or reb.gain>peb.gain)then
peb=reb
end
end
if peb then
return peb,string.format(Jcd[2802],math.floor(feb.leak*100))
end
end
local teb=feb.future<feb.wantLeft*1.1
local ueb,veb,web=true,nil,nil
if leb then
ueb,veb,web=cb.keepsUp(feb,eeb,leb.cost,0,leb.gain)
end
local xeb=feb.coming and not cb.keepsUp(feb,eeb,0,0,0)
local yeb=false
if W.random and leb and not keb and feb.attackers>=2 and leb.payback<=feb.left/3 then
local zeb=0
for Aeb,Beb in ipairs(W.mine or{})do
if R.isFarm(Beb._stats.id.Value)then
zeb=zeb+1
end
end
yeb=not leb.place or zeb<4
end
if xeb and feb.attackers>0 then
keb=true
end
local Ceb=math.max(1,feb.incomeRate or 20)
local Deb=feb.waveSec or 20
local function Eeb(Feb,Geb,Heb)
local Ieb=math.max(0,(Feb.cost-feb.money)/Ceb)
local Jeb=Feb.gain*math.max(0,Heb-Ieb)
if Geb then
local Keb=math.max(0,feb.money-Feb.cost)
local Leb=Ieb+math.max(0,(Geb.cost-Keb)/Ceb)
Jeb=Jeb+Geb.gain*math.max(0,Heb-Leb)
