Meb,Neb=Veb or meb,Ueb>1 and Jcd[2803]or Jcd[2804]
elseif leb and jeb and teb and not keb and ueb then
Meb=leb
Neb=string.format(Jcd[2805],leb.payback,feb.left,feb.coming and#feb.coming or 0)
elseif yeb then
Meb=leb
Neb=string.format(Jcd[2806],leb.payback,feb.left)
elseif meb then
Meb=meb
if xeb then
Neb=string.format(Jcd[2807])
elseif keb then
Neb=string.format(Jcd[2808],math.floor(feb.pressure*100),math.floor(geb*100))
elseif leb and not ueb then
Neb=string.format(Jcd[2809],veb or 1,math.floor((web or 0)*100))
elseif leb and ieb then
Neb=string.format(Jcd[2810],math.min(999,math.floor(feb.clearSec)),math.floor(heb))
elseif leb and feb.piling then
Neb=string.format(Jcd[2811],feb.enemies)
elseif leb and not jeb then
Neb=Jcd[2812]
elseif leb and not teb then
Neb=Jcd[2813]
else
Neb=Jcd[2814]
end
end
if not Meb then
return nil
end
if Meb.cost>feb.money then
local Web
if not Meb.farm then
local Xeb=((feb.pressure or 0)>=0.95 and 0.5 or keb and 2 or 6)*Deb
local Yeb
