end
local wLb=0
for xLb=2,#tLb do
wLb=wLb+(tLb[xLb]-tLb[xLb-1]).Magnitude
end
local yLb=0
for zLb=2,#tLb do
local ALb,BLb=tLb[zLb-1],tLb[zLb]
local CLb=(BLb-ALb).Magnitude
local DLb=math.max(1,math.floor(CLb/2))
for ELb=0,DLb-1 do
local FLb=ALb:Lerp(BLb,ELb/DLb)
table.insert(W.samples,{pos=FLb,prog=(yLb+CLb*ELb/DLb)/math.max(1,wLb),lane=rLb.Name})
end
yLb=yLb+CLb
end
