end
if not V.every(Jcd[3168],60)then
return
end
local xMb=U.rec(W.key)
local yMb=tonumber(xMb.timed)or 0
local zMb=(yMb>0 and(xMb.sec or 0)>0)and math.max(0.5,((xMb.gems or 0)-200*yMb)/(xMb.sec/60))or 2.5
