if not R.isFarm(QOb.id.Value)and QOb:FindFirstChild(Jcd[1735])then
table.insert(NOb,{p=Q.flat(POb:GetPivot().Position),r=QOb.range.Value*(R.SUMMONER[QOb.id.Value]and R.SUMMONER[QOb.id.Value].reach or 1),air=W.canAir(POb)})
end
