local ROb,SOb=0,0
if#NOb>0 then
for TOb,UOb in ipairs(W.samples)do
if UOb.prog>SOb then
local VOb=Q.flat(UOb.pos)
for WOb,XOb in ipairs(NOb)do
if(VOb-XOb.p).Magnitude<=XOb.r then
if UOb.prog>ROb then
ROb=UOb.prog
end
if XOb.air then
SOb=UOb.prog
break
end
end
end
end
end
