function W.learn()
local zec=W.calRun and W.calRun.potBy
if type(zec)~=Jcd[1580]then
return
end
pcall(W.sampleHelpers,true)
local Aec={}
for Bec,Cec in pairs(W.ownDealt or{})do
if not R.isFarm(Cec.id)then
Aec[Cec.id]=(Aec[Cec.id]or 0)+(tonumber(Cec.v)or 0)
end
end
for Dec,Eec in pairs(W.helperDealt or{})do
if Eec.owner and R.SUMMONER[Eec.owner]then
Aec[Eec.owner]=(Aec[Eec.owner]or 0)+(tonumber(Eec.v)or 0)
end
end
local Fec,Gec=0,0
for Hec,Iec in pairs(zec)do
if Iec>0 then
Fec=Fec+(Aec[Hec]or 0)
Gec=Gec+Iec
end
end
if Fec<=0 or Gec<=0 then
return
end
local Jec=Fec/Gec
W.lastEff={}
for Kec,Lec in pairs(zec)do
if Lec>0 and Lec/Gec>0.02 then
local Mec=N.learn[Kec]or{eff=1,n=0}
local Nec=math.max(0.02,0.25*math.sqrt(30/(30+Mec.n)))
local Oec=Q.clamp(((Aec[Kec]or 0)/Lec)/Jec,0.3,3)
W.lastEff[Kec]=math.floor(Oec*1000+0.5)/1000
Mec.eff=Mec.eff+(Oec-Mec.eff)*Nec
Mec.n=Mec.n+1
N.learn[Kec]=Mec
end
end
local Pec=R.mapKey((W.info and W.info.map)or(W.ld and W.ld.map))
if Pec and next(W.lastEff)then
N.mapLearn=type(N.mapLearn)==Jcd[1580]and N.mapLearn or{}
local Qec=type(N.mapLearn[Pec])==Jcd[1580]and N.mapLearn[Pec]or{}
for Rec,Sec in pairs(W.lastEff)do
local Tec=type(Qec[Rec])==Jcd[1580]and Qec[Rec]or{eff=Sec,n=0}
local Uec=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Tec.n)or 0))))
Tec.eff=(tonumber(Tec.n)or 0)==0 and Sec or((tonumber(Tec.eff)or Sec)+(Sec-(tonumber(Tec.eff)or Sec))*Uec)
Tec.n=(tonumber(Tec.n)or 0)+1
Qec[Rec]=Tec
end
Qec._at=os.time()
N.mapLearn[Pec]=Qec
if Q.count(N.mapLearn)>80 then
local Vec,Wec
for Xec,Yec in pairs(N.mapLearn)do
if not Wec or(tonumber(Yec._at)or 0)<Wec then
Vec,Wec=Xec,tonumber(Yec._at)or 0
end
end
N.mapLearn[Vec]=nil
end
end
end
