for rmc,smc in ipairs(W.samples)do
if smc.prog>=gmc.prog and(Q.flat(smc.pos)-qmc).Magnitude<=hmc then
pmc=pmc+1
end
end
if not kmc or pmc>kmc then
jmc,kmc=omc,pmc
end
end
end
end
return jmc,kmc or 0
end
function W.focusGain(tmc)
local umc=W.focus
if not umc then
return 1
end
local vmc=tmc._stats
if not vmc:FindFirstChild(Jcd[1735])then
return 1
end
local wmc,xmc=Q.flat(tmc:GetPivot().Position),vmc.range.Value
if umc.fly and not W.canAir(tmc)then
return 0.02
end
if(wmc-Q.flat(umc.pos)).Magnitude<=xmc then
return 1
end
return(wmc-Q.flat(umc.pos)).Magnitude<=xmc*1.5 and 0.3 or 0.02
end
W.cashTried=setmetatable({},{__mode=Jcd[1780]})
function W.lastWaveCash()
if not(W.total and W.wave()>=W.total and not W.infinite)or W.spellBusy then
return
end
local ymc=L.session()
local zmc
for Amc,Bmc in pairs((ymc and ymc.ingame_spells)or{})do
