W.mergeIds={}
function W.mergeScan()
W.mergePlan,W.mergeIds=nil,{}
if not W.random then
return
end
local Nmc=L.session()
local Omc=false
W.cloneCard=false
for Pmc,Qmc in pairs((Nmc and Nmc.ingame_spells)or{})do
if Qmc==Jcd[3509]then
Omc=true
elseif Qmc==Jcd[3547]then
W.cloneCard=true
end
end
local Rmc={}
local Smc=N.fh.noMerge or{}
for Tmc,Umc in ipairs(W.mine or{})do
local Vmc=Umc._stats
local Wmc=Vmc.id.Value
if not R.isFarm(Wmc)and not R.allyBuff(Wmc)and not R.idol(Wmc)and Vmc:FindFirstChild(Jcd[3548])and(Smc[Wmc]or 0)<2 then
local Xmc,Ymc=pcall(W.liveDps,Umc,Wmc)
Rmc[Wmc]=Rmc[Wmc]or{}
table.insert(Rmc[Wmc],{m=Umc,lvl=Vmc.upgrade.Value,max=Vmc.max_upgrade.Value,dps=Xmc and Ymc or 0})
end
end
local Zmc={}
for _mc,anc in ipairs(W.team or{})do
if anc.hand then
Zmc[anc.id]=true
end
end
local bnc={}
for cnc,dnc in pairs(Rmc)do
table.sort(dnc,function(enc,fnc)
if enc.dps~=fnc.dps then
return enc.dps>fnc.dps
end
return enc.lvl>fnc.lvl
end)
table.insert(bnc,{id=cnc,dps=dnc[1].dps*W.airBoost(dnc[1].m)*W.reach(dnc[1].m)})
end
table.sort(bnc,function(gnc,hnc)
return gnc.dps>hnc.dps
end)
for jnc=1,math.min(3,#bnc)do
W.mergeIds[bnc[jnc].id]=true
end
local knc
for lnc,mnc in pairs(Rmc)do
local nnc=table.clone(mnc)
table.sort(nnc,function(onc,pnc)
if onc.lvl~=pnc.lvl then
return onc.lvl<pnc.lvl
end
return onc.dps<pnc.dps
end)
for qnc,rnc in ipairs(nnc)do
if rnc.m==W.freshM and qnc>1 then
table.remove(nnc,qnc)
table.insert(nnc,1,rnc)
break
end
end
local snc,tnc,unc,vnc
for wnc,xnc in ipairs(nnc)do
local ync,znc=Q.flat(xnc.m:GetPivot().Position),xnc.m._stats.range.Value
local Anc,Bnc,Cnc=0,0,nil
for Dnc,Enc in ipairs(mnc)do
if Enc~=xnc and(Q.flat(Enc.m:GetPivot().Position)-ync).Magnitude<=znc then
Anc,Bnc=Anc+Enc.dps,Bnc+1
if not Cnc or Enc.dps>Cnc.dps then
Cnc=Enc
end
end
end
if Bnc>0 then
snc,tnc,unc,vnc=xnc,Anc,Bnc,Cnc
break
end
end
vnc=vnc or mnc[1]
local Fnc=vnc.dps*W.airBoost(vnc.m)*W.reach(vnc.m)*(lnc==W.planId and 2 or 1)
if(W.mergeIds[lnc]or lnc==W.planId)and(snc or Zmc[lnc])and(not knc or Fnc>knc.score)then
knc={id=lnc,top=vnc,fresh=snc,near=tnc or 0,n=unc or 0,coming=Zmc[lnc],score=Fnc}
end
end
W.planId,W.freshM=knc and knc.id,knc and knc.fresh and knc.fresh.m
W.mergeHeldAt=(Omc and knc and knc.fresh)and(W.mergeHeldAt or W.wave())or nil
if not knc then
return E.status(Jcd[3486],Jcd[3549])
end
local Gnc,Hnc=W.wave(),(W.total or 30)-W.wave()
local Inc=(W.pressure or 0)>=math.min(M.dangerReach,((W.depth and W.depth.units>0 and W.depth.covEnd)or 1)*0.9)
local Jnc=knc.fresh
local Knc=not Inc and Hnc>3
knc.waits=Jnc and Jnc.lvl<=knc.top.lvl and knc.top.lvl<knc.top.max and Knc or false
local Lnc=(not Jnc or Jnc.lvl>=knc.top.lvl)and knc.coming and Knc
local Mnc=W.cloneCard and knc.top.lvl>=knc.top.max and Knc
local Nnc=Jnc and Jnc.lvl>knc.top.lvl and knc.near<0.3*Jnc.dps
knc.ready=Omc and Jnc~=nil and not Nnc and(not(knc.waits or Lnc or Mnc)or Gnc-(W.mergeHeldAt or Gnc)>=5)
W.holdNoCardAt=(knc.waits and not Omc)and(W.holdNoCardAt or Gnc)or nil
knc.hold=knc.waits and(Omc or Gnc-(W.holdNoCardAt or Gnc)<4)
W.mergePlan=knc
E.status(Jcd[3486],Jnc and string.format(Jcd[3550],R.name(knc.id),knc.n,knc.n==1 and Jcd[3551]or Jcd[3552],Jnc.lvl,knc.ready and Jcd[3553]or(Omc and Jcd[3554]or Jcd[3555]))or string.format(Jcd[3556],R.name(knc.id)))
end
function W.mergeHold(Onc)
