table.insert(ioc[loc],koc)
end
end
for moc,noc in pairs(ioc)do
if#noc>=2 then
table.sort(noc,function(ooc,poc)
return ooc._stats.upgrade.Value<poc._stats.upgrade.Value
end)
for qoc,roc in ipairs(noc)do
local soc,toc=Q.flat(roc:GetPivot().Position),roc._stats.range.Value
local uoc,voc=0,0
for woc,xoc in ipairs(noc)do
if xoc~=roc and(Q.flat(xoc:GetPivot().Position)-soc).Magnitude<=toc then
uoc,voc=uoc+(tonumber(xoc._stats.farm_amount.Value)or 0),voc+1
end
end
if voc>0 then
return roc,uoc,voc
end
end
end
end
end
function W.farmMergeSpot(yoc)
