return
end
local apc=W.money()
local bpc=(W.pressure or 0)>=math.min(M.dangerReach,((W.depth and W.depth.units>0 and W.depth.covEnd)or 1)*0.9)
local cpc,dpc,epc
for fpc,gpc in ipairs(W.mine)do
local hpc=gpc._stats.id.Value
if not R.isFarm(hpc)and not R.allyBuff(hpc)and hpc~=Jcd[3178]then
local ipc,jpc=pcall(W.liveDps,gpc,hpc)
local kpc=ipc and jpc and jpc*W.airBoost(gpc)*W.reach(gpc)
