local Bpc,Cpc,Dpc=W.farmMergePair()
vpc=Bpc
wpc=string.format(Jcd[3566],Dpc,R.name(Bpc._stats.id.Value))
W.farmMergeBefore={own=tonumber(Bpc._stats.farm_amount.Value)or 0,inc=Cpc}
elseif upc==Jcd[3547]then
local Epc=not bpc and lpc and lpc.fresh and lpc.top.lvl<lpc.top.max
W.cloneWaitAt=Epc and(W.cloneWaitAt or W.wave())or nil
local Fpc=Epc and W.wave()-W.cloneWaitAt<5
local Gpc,Hpc
