local Rpc,Spc=pcall(W.liveDps,vpc,Qpc.id.Value)
Ppc={id=Qpc.id.Value,pos=vpc:GetPivot().Position,dps=Rpc and tonumber(Spc)or 0,lvl=Qpc.upgrade.Value,spent=Qpc:FindFirstChild(Jcd[3507])and tonumber(Qpc.total_spent.Value)or 0}
end
task.spawn(function()
local Tpc
if vpc then
