E.log(1,Jcd[3503],string.format(Jcd[3577],W.SPELL_NAMES[upc]or tostring(upc),vpc and(Jcd[1869]..Upc)or Jcd[507],wpc))
E.status(Jcd[3396],string.format(Jcd[3578],W.SPELL_NAMES[upc]or tostring(upc),vpc and(Jcd[1869]..Upc)or Jcd[507],wpc))
