function W.trainCount()
local Vpc=N.train.on
if not(Vpc and W.trainee)then
return
end
local Wpc=0
for Xpc,Ypc in ipairs(W.mine)do
local Zpc=Ypc._stats
local _pc=Zpc:FindFirstChild(Jcd[3298])and Zpc.uuid.Value
local aqc=_pc==W.trainee and Zpc:FindFirstChild(Vpc.what==Jcd[2100]and Jcd[3580]or Jcd[2068])
if aqc then
Wpc=Wpc+(tonumber(aqc.Value)or 0)
end
end
W.trainTk=math.max(W.trainTk or 0,Wpc)
E.status(Jcd[2478],string.format(Jcd[3581],R.name(Vpc.id),W.trainTk,Vpc.what,Q.fmt(Vpc.have+(Vpc.got or 0)+W.trainTk),Q.fmt(Vpc.need)))
end
function W.trainDone(bqc,cqc)
local dqc=N.train.on
if not(dqc and W.trainee)then
return
end
W.trainCount()
local eqc=W.trainTk or 0
dqc.got=(dqc.got or 0)+eqc
local fqc=N.trainSim[bqc]and tonumber(N.trainSim[bqc].tk)
if not W.joinedMid then
local gqc=N.train.real[bqc]or{n=0,sum=0}
gqc.n,gqc.sum=gqc.n+1,gqc.sum+eqc
N.train.real[bqc]=gqc
if fqc and fqc>0 then
local hqc=N.train.cal
hqc.real,hqc.sim,hqc.n=(hqc.real or 0)+eqc,(hqc.sim or 0)+fqc,(hqc.n or 0)+1
end
end
table.insert(N.train.log,1,{key=bqc,got=eqc,won=cqc,at=os.time()})
while#N.train.log>20 do
table.remove(N.train.log)
end
E.log(1,Jcd[2471],string.format(Jcd[3582],R.name(dqc.id),eqc,dqc.what,cqc and Jcd[1965]or Jcd[1966],fqc and string.format(Jcd[3583],fqc)or Jcd[507],Q.fmt(fb.realHave(dqc)),Q.fmt(dqc.need)))
if not cqc then
N.train.bad[bqc]=os.time()+6*3600
E.log(1,Jcd[2471],Jcd[3584])
end
end
function W.finish()
if W.finished then
return
end
W.finished=true
local iqc
local jqc=Q.now()
while Q.now()-jqc<8 do
iqc=W.result or(L.GUIS.results_ui and L.GUIS.results_ui.settings)
if iqc then
break
end
task.wait(0.25)
end
local kqc=iqc and iqc.victory or false
local lqc=W.infinite and W.wave()or nil
if lqc then
kqc=true
end
local mqc=W.key
local nqc=U.rec(mqc)
if lqc and not W.joinedMid and not W.stopping then
nqc.waveSum,nqc.waveN=(tonumber(nqc.waveSum)or 0)+lqc,(tonumber(nqc.waveN)or 0)+1
nqc.waveBest=math.max(tonumber(nqc.waveBest)or 0,lqc)
